 "content": "def transform(grid):
    """Repeat the non-background pattern found between full separator lines."""
    h, w = len(grid), len(grid[0])
    # ARC backgrounds are the most frequent color in these examples.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # A uniform line in a non-background color is a separator.
    row_seps = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]

    if row_seps and not col_seps:
        bounds = [-1] + row_seps + [h]
        bands = [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]
        bands = [(a, b) for a, b in bands if a < b]
        period = min(b - a for a, b in bands)
        template = [[background for _ in range(w)] for _ in range(period)]
        for a, b in bands:
            for offset in range(min(period, b - a)):
                for c in range(w):
                    value = grid[a + offset][c]
                    if value != background:
                        template[offset][c] = value
        out = [row[:] for row in grid]
        for a, b in bands:
            for offset in range(b - a):
                for c in range(w):
                    if template[offset % period][c] != background:
                        out[a + offset][c] = template[offset % period][c]
        return out

    if col_seps and not row_seps:
        bounds = [-1] + col_seps + [w]
        bands = [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]
        bands = [(a, b) for a, b in bands if a < b]
        period = min(b - a for a, b in bands)
        template = [[background for _ in range(period)] for _ in range(h)]
        for a, b in bands:
            for offset in range(min(period, b - a)):
                for r in range(h):
                    value = grid[r][a + offset]
                    if value != background:
                        template[r][offset] = value
        out = [row[:] for row in grid]
        for a, b in bands:
            for offset in range(b - a):
                for r in range(h):
                    if template[r][offset % period] != background:
                        out[r][a + offset] = template[r][offset % period]
        return out
    return [row[:] for row in grid]

